import React, { useState } from 'react';
import { FaGithub } from '@react-icons/all-files/fa/FaGithub';
import { IoPlay } from '@react-icons/all-files/io5/IoPlay';
import { FiChevronDown } from '@react-icons/all-files/fi/FiChevronDown';
import { FiChevronUp } from '@react-icons/all-files/fi/FiChevronUp';

import {
  ProjectItem,
  categoryTabs,
  ALL_CATEGORY,
  ProjectCategory,
} from '../../data/projectSections';
import PageLayout from '../layouts/PageLayout';
import PageHeader from '../shared/PageHeader';
import SEO from '../shared/SEO';
import H, { hLevel } from '../shared/H';
import ButtonLink from '../shared/ButtonLink';

type ProjectsScreenProps = {
  projects: ProjectItem[];
};

const ProjectCard = ({ project }: { project: ProjectItem }): React.ReactElement => {
  const [expanded, setExpanded] = useState(false);

  const gitHubLink = project.gitHubUrl
    ? { url: project.gitHubUrl, caption: 'GitHub' }
    : undefined;

  const demoLink = project.demoUrl
    ? { url: project.demoUrl, caption: 'Demo' }
    : undefined;

  const tags = project.tags?.length ? (
    <div className="flex flex-wrap gap-1.5 mt-3">
      {project.tags.map((tag) => (
        <span
          key={tag}
          className="inline-block bg-gray-200 rounded-sm px-2 py-0.5 text-xs font-normal text-gray-600"
        >
          {tag}
        </span>
      ))}
    </div>
  ) : null;

  const hasDetails = project.details && project.details.length > 0;

  const detailsToggle = hasDetails ? (
    <button
      type="button"
      onClick={() => setExpanded(!expanded)}
      className="inline-flex items-center bg-white py-1.5 px-3 rounded shadow-sm border border-solid border-gray-300 text-sm transition duration-200 ease-in-out hover:bg-black hover:text-white"
    >
      {expanded ? <FiChevronUp className="mr-1.5" /> : <FiChevronDown className="mr-1.5" />}
      {expanded ? 'Less' : 'Details'}
    </button>
  ) : null;

  const detailsList = expanded && project.details ? (
    <div className="border-t border-gray-100 pt-4">
      <ul className="space-y-1.5">
        {project.details.map((detail, i) => (
          // eslint-disable-next-line react/no-array-index-key
          <li key={i} className="flex text-sm text-gray-600 font-light">
            <span className="text-gray-400 mr-2">&rsaquo;</span>
            <span>{detail}</span>
          </li>
        ))}
      </ul>
    </div>
  ) : null;

  const thumbnail = project.thumbnail ? (
    <div className="flex-shrink-0 w-full sm:w-48 h-36 overflow-hidden rounded-t-md sm:rounded-t-none sm:rounded-l-md">
      <img
        src={project.thumbnail}
        alt={project.title}
        className="w-full h-full object-cover object-top"
      />
    </div>
  ) : null;

  return (
    <div className="shadow-card rounded-md overflow-hidden bg-white">
      <div className="flex flex-col sm:flex-row">
        {thumbnail}
        <div className="flex-1 p-5">
          <div className="flex items-center justify-between mb-2">
            <H level={hLevel.h3} className="font-semibold">
              {project.title}
            </H>
            <span className="text-xs text-gray-400 ml-3 whitespace-nowrap">
              {project.category}
            </span>
          </div>
          <p className="font-light text-sm text-gray-600 mb-3">
            {project.description}
          </p>
          <div className="flex flex-wrap items-center gap-2">
            {gitHubLink ? (
              <ButtonLink
                link={gitHubLink}
                startEnhancer={<FaGithub />}
              >
                Source
              </ButtonLink>
            ) : null}
            {demoLink ? (
              <ButtonLink
                link={demoLink}
                startEnhancer={<IoPlay />}
              >
                Demo
              </ButtonLink>
            ) : null}
            {detailsToggle}
          </div>
          {tags}
        </div>
      </div>
      {detailsList ? (
        <div className="px-5 pb-5">
          {detailsList}
        </div>
      ) : null}
    </div>
  );
};

const ProjectsScreen = (props: ProjectsScreenProps): React.ReactElement => {
  const { projects } = props;
  const [activeCategory, setActiveCategory] = useState<string>(ALL_CATEGORY);

  const filteredProjects = activeCategory === ALL_CATEGORY
    ? projects
    : projects.filter((p) => p.category === activeCategory);

  const getCategoryCount = (category: string): number => {
    if (category === ALL_CATEGORY) return projects.length;
    return projects.filter((p) => p.category === category).length;
  };

  return (
    <PageLayout>
      <SEO
        title="Projects"
        description="Applications, tools, LLM alignment experiments, and learning projects by Claudia Flores-Saviaga"
      />
      <PageHeader>Projects</PageHeader>

      {/* Category tabs */}
      <div className="border-b border-gray-200 mb-8">
        <div className="flex flex-wrap gap-1">
          {categoryTabs.map((tab) => {
            const isActive = activeCategory === tab.category;
            const count = getCategoryCount(tab.category);
            return (
              <button
                key={tab.category}
                type="button"
                onClick={() => setActiveCategory(tab.category)}
                className={`
                  px-4 py-2.5 text-sm font-medium transition duration-200 ease-in-out
                  border-b-2 -mb-px
                  ${isActive
                    ? 'border-red-600 text-red-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                  }
                `}
              >
                {tab.label}
                <span className={`ml-1.5 text-xs ${isActive ? 'text-red-400' : 'text-gray-400'}`}>
                  ({count})
                </span>
              </button>
            );
          })}
        </div>
      </div>

      {/* Project list */}
      <div className="grid gap-6 grid-cols-1">
        {filteredProjects.map((project) => (
          <ProjectCard key={project.title} project={project} />
        ))}
      </div>
    </PageLayout>
  );
};

export default ProjectsScreen;
